// One item per page to check. Edit this list.
return [
  { json: { competitor: 'Example A', url: 'https://example.com/pricing' } },
  { json: { competitor: 'Example B', url: 'https://example.org/pricing' } },
];

// Pull price-like strings out of each page's markdown.
const pricePattern = /(?:[$\u20ac\u00a3]\s?\d[\d,]*(?:\.\d{1,2})?)(?:\s?(?:\/|per)\s?(?:mo|month|yr|year|user|seat))?/gi;
return $input.all().map((item, index) => {
  const source = $('Pages to check').all()[index]?.json ?? {};
  const markdown = item.json.content ?? '';
  const prices = [...new Set(markdown.match(pricePattern) ?? [])].slice(0, 10);
  return {
    json: {
      date: new Date().toISOString().slice(0, 10),
      competitor: source.competitor,
      url: item.json.url ?? source.url,
      status: item.json.status,
      prices: prices.join(' | '),
    },
  };
});
